    if (val is null && !EnvironmentVariableIsSet("MY_FLAG"))
    {
        Console.WriteLine("MY_FLAG not set, using default");
    }
}

static bool EnvironmentVariableIsSet(string name)
{
    // After .NET 9, GetEnvironmentVariable returns "" for empty vars
    // on Linux instead of null. Check the raw environment to confirm.
    return Environment.GetEnvironmentVariable(name) != null;
}

