{
    void CheckFlag()
    {
        // .NET 9 breaking change: On Linux, Environment.GetEnvironmentVariable
        // now returns "" for empty env vars instead of null (.NET 8 returned null
        // for both "not set" and "empty"). Update checks accordingly.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val is null)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
        else if (val.Length == 0)
        {
            Console.WriteLine("MY_FLAG explicitly empty");
        }
    }
}

